text(await tools.exec_command({cmd:"/home/maxg/travel-expense-claim/.venv/bin/python -B - <<'PY'
import json,hashlib
from pathlib import Path
from collections import Counter
from normalization import normalize as n
run=Path('artifacts/runs/omega4-live-20261020-attempt002'); out=Path('artifacts/normalizations/omega4-attempt002-normalization-v1')
b=(out/'records.v1.json').read_bytes(); d=json.loads(b); r=json.loads((out/'parsing-report.v1.json').read_bytes()); m=json.loads((run/'sources.json').read_bytes())
n.verify_run(run)
print('VERIFIED acquisition bindings, responses, source hashes, supplement and provenance')
print('manifest hash',hashlib.sha256((run/'sources.json').read_bytes()).hexdigest(),d['acquisition_manifest_sha256'])
print('records hash match',hashlib.sha256(b).hexdigest()==r['normalized_records_sha256'])
print('source bindings match',all(s=={k:e[k] for k in s} for s in d['sources'] for e in m['files'] if e['source_id']==s['source_id']))
fresh,report=n.build(run)
print('in-memory parse equals saved records',fresh==d)
print('in-memory report equals saved',report=={k:v for k,v in r.items() if k!='normalized_records_sha256'})
print('counts',d['source_counts']); print('issues',Counter(i['severity'] for i in r['issues']))
byrid={c['record_id']:c for c in d['claims']}
print('review gaps',[(byrid[i['record_id']]['claim_id'],byrid[i['record_id']]['revision']) for i in r['issues'] if i['severity']=='observation'])
print('receipt/trip/merchant links',len(d['cross_source_checks']),sum(len(c['receipt_matches'])==1 and not c['receipt_mismatched_fields'] for c in d['cross_source_checks']),sum(len(c['trip_matches'])==1 for c in d['cross_source_checks']),sum(len(c['merchant_identity_matches'])==1 for c in d['cross_source_checks']))
for c in d['claims']:
 if c['claim_id'] in ['C03','C24','C09','C18','C19','C121']:
  print('CLAIM',json.dumps({k:v for k,v in c.items() if k not in ['raw_text','raw_fields','expenses']})); print('EXPENSES',[(e['expense_id'],e['receipt_id'],e['original_amount']) for e in c['expenses']])
for c in d['cross_source_checks']:
 if not c['merchant_identity_matches']:print('MISSING',json.dumps(c))
for tab in ['Finance activity','Travel cancellations']:
 for row in d['workbook'][tab]['rows']:
  v=row['values']
  if v.get('Claim reference') in ['C18','C19'] or v.get('Activity reference')=='F-C01-1' or v.get('Cancellation activity reference') in ['TC122-confirmed','TC121-confirmed','TC018-confirmed']:print('EVENT',row['record_id'],json.dumps(v))
print('repeated',json.dumps(r['repeated_events']))
print('unparsed claims',sum('unparsed_expense_text' in c for c in d['claims']))
PY","max_output_tokens":6500,"yield_time_ms":1000}));

